SELECT CASE WHEN amount >= 1530 THEN 'high' WHEN amount >= 470 THEN 'mid' ELSE 'low' END AS amount_bucket, status, SUM(CASE WHEN status = 'CANCELLED' THEN shipping_fee ELSE 0 END) AS cancelled_shipping_fee, MAX(order_date) AS latest_order_date, MAX(shipping_fee) - MIN(shipping_fee) AS shipping_fee_range FROM orders WHERE YEAR(order_date) = 2025 GROUP BY 1, 2 ORDER BY amount_bucket
